export function escapeHtml(value: unknown): string {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

export function cssEscape(value: unknown): string {
  const text = String(value || "");
  if (window.CSS?.escape) return window.CSS.escape(text);
  return text.replace(/["\\]/g, "\\$&");
}

export function errorMessage(error: unknown, fallback: string): string {
  return error instanceof Error ? error.message || fallback : fallback;
}

export function prefersReducedMotion(): boolean {
  return Boolean(window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches);
}

declare global {
  interface Window {
    MbaiAndroid?: {
      downloadImage(url: string, filename: string, mimeType: string): void;
      getCacheSize(): string;
      clearCache(): void;
    };
  }
}

export function isMbaiAndroidApp(): boolean {
  return Boolean(window.MbaiAndroid && /\bMoBaiApp\//.test(navigator.userAgent));
}

export async function clientDirectDownload(url: string, filename: string): Promise<void> {
  if (!url) return;
  const absoluteUrl = new URL(url, window.location.origin).toString();
  if (isMbaiAndroidApp()) {
    window.MbaiAndroid?.downloadImage(absoluteUrl, filename || "", "");
    return;
  }

  const link = document.createElement("a");
  link.href = absoluteUrl;
  if (filename) link.download = filename;
  else link.setAttribute("download", "");
  link.rel = "noopener noreferrer";
  if (new URL(absoluteUrl).origin !== window.location.origin) link.target = "_blank";
  link.style.display = "none";
  document.body.append(link);
  link.click();
  link.remove();
}

export function appCacheSizeBytes(): number | null {
  if (!isMbaiAndroidApp()) return null;
  const parsed = Number.parseInt(window.MbaiAndroid?.getCacheSize() || "", 10);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;
}

export function clearMbaiAppCache(): boolean {
  if (!isMbaiAndroidApp()) return false;
  window.MbaiAndroid?.clearCache();
  return true;
}
